"""Статья «Текущий ремонт: договоры, сметы и расчёты в 2026 году» для раздела «Расчёт смет».

Исходный отчёт подготовлен ООО «Тэга плюс» (109 страниц). Здесь он проверен, сокращён и приведён к стилю сайта.
Подтверждено по открытым источникам: Кодекс об архитектурной, градостроительной и строительной деятельности от 17.07.2023 № 289-З (ст. 83 о ремонте);
Положение о неизменной договорной (контрактной) цене, утв. постановлением Совмина от 18.11.2011 № 1553; корректировка цены по основаниям подп. 1.8 п. 1 постановления Совмина от 15.06.2019 № 395 для бюджетных средств;
стоимость человеко-часа рабочего 4 разряда 12,46 руб. (постановление Минстройархитектуры от 16.02.2024 № 6) и 14,47 руб. с 01.05.2025 (от 10.03.2025 № 34);
постановление Минстройархитектуры от 17.12.2025 № 146 (нормы ОХР, ОПР, плановой прибыли, с 13.02.2026; для текущего ремонта к плановой прибыли коэффициент 1,115) и Инструкция от 13.10.2025 № 116.
Не удалось подтвердить и не вошло в статью: значение человеко-часа на 2026 год, проценты норм ОХР и плановой прибыли, пороги закупок в рублях и базовые величины, пределы 10 % и 15 % изменения договора по новым актам 2026 года,
постановление Совмина от 30.10.2026 № 561 и его новации, постановление Минэкономики о прогнозных индексах 2026 года и их значения, ссылки на административные статьи, Закон от 17.07.2026 № 170-З, НЗТ 2026 года.
Они названы в статье как параметры, которые сверяют по тексту действующего акта.
"""
from art_heat import _sec, _ul, _tbl, _note, _box, _p, _errs, _kpis
from art_repair_figs import f_chain, f_ladder


def article():
    s = ""
    s += _kpis([("2 документа", "дефектный акт и локальная смета: основа текущего ремонта вместо проекта"), ("только локальная", "сводного сметного расчёта и объектной сметы по текущему ремонту не составляют"),
                ("дата и срок", "заказчик задаёт их в дефектном акте, от них зависят индексы и цена"), ("не капитал", "текущий ремонт это расходы периода, а не увеличение стоимости основного средства")])
    s += f_chain()
    s += _box("Главный принцип",
              "Текущий ремонт упрощён по документам, но не по дисциплине. Проекта и разрешений нет, поэтому всё держится на дефектном акте: что сломано, сколько, когда начнём и сколько продлится. "
              "Что не записано в акт, то не попадёт в смету, а значит, потом его придётся оформлять как дополнительные работы.")

    s += _sec("0", "Где проходит граница текущего ремонта",
              _p("Ремонт делится на текущий и капитальный (ст. 83 Кодекса). Рядом стоят техническое обслуживание, модернизация и реконструкция. От вида работ зависит всё: нужен ли проект, аттестат подрядчика и уведомление о работах.")
              + f_ladder()
              + _tbl(["Вид", "Суть", "Что нужно"], [
                  ["Техническое обслуживание", "поддержание в порядке: мелкие неисправности, регулировка, подготовка к сезону", "договор на обслуживание, регламент и график"],
                  ["Текущий ремонт", "предупреждение износа, устранение повреждений, улучшение эстетики", "дефектный акт, локальная смета, договор подряда"],
                  ["Капитальный ремонт", "восстановление и замена конструкций, деталей, оборудования", "проектная и разрешительная документация"],
                  ["Модернизация, реконструкция", "новые системы, перенос перегородок, смена назначения или параметров объекта", "проект, разрешения, подрядчик с аттестатом"]])
              + _p("Практические признаки того, что это уже не текущий ремонт: новая инженерная система вместо ремонта старой, перепланировка, смена назначения помещения, замена несущих конструкций, замена большей части однотипных элементов. "
                   "Сопоставляйте перечень работ с перечнями в СП 1.04.01-2021, если вы их применяете, и фиксируйте решение приказом.")
              + _note("Порог «замена не более 40 % однотипных элементов» часто называют в практике. Это ориентир, а не норма: в акте решает перечень работ."))

    s += _sec("1", "Что не нужно для текущего ремонта",
              _p("По ст. 83 Кодекса работы по текущему ремонту выполняются без проектной документации, без разрешительной документации на строительство, без аттестатов соответствия и без уведомления о выполнении строительно-монтажных работ. Основание: дефектный акт и смета.")
              + _ul(["<b>Аттестат подрядчика</b> на чисто текущий ремонт не требуют. Требование аттестата в закупке на такие работы надо обосновывать особо, а при смешанном договоре аттестат нужен на ту часть, где проект обязателен.",
                     "<b>Уведомление</b> о начале работ не направляют. Лишнее уведомление может привести к лишним проверкам.",
                     "<b>Проект не нужен, а акт нужен.</b> Он заменяет проект как основание для сметы и фиксирует объёмы.",
                     "<b>Дата начала и срок</b> работ в отсутствие разрешительной документации задаёт сам заказчик, прямо в акте."]))

    s += _sec("2", "Дефектный акт: что в нём должно быть",
              _p("Форма дефектного акта утверждена Минстройархитектуры, свою форму придумывать нельзя. Акт составляет комиссия по приказу руководителя заказчика после осмотра. Он служит основой объёмов для сметы.")
              + _tbl(["Реквизит", "Зачем"], [
                  ["Объект, адрес, инвентарный номер", "идентификация и учёт"],
                  ["Дефекты с количеством (шт., м², м.п., м³)", "объёмы для сметы: без них смета «на глаз», а допработы не отделить от основных"],
                  ["Виды и объёмы работ", "предмет договора и подтверждение вида «текущий ремонт»"],
                  ["Стеснённые и усложнённые условия", "основание для повышающих коэффициентов; задним числом их добавить трудно"],
                  ["Дата начала и срок выполнения работ", "от них считаются прогнозные индексы и цена"],
                  ["Обоснование прочих средств (отходы, разработка сметы, экспертиза)", "эти статьи включают в смету, только если они обоснованы в акте"],
                  ["Условия производства работ (люди, ночные работы, шум и пыль)", "обоснование удорожающих факторов"]])
              + _errs([("Нет даты начала и срока", "акт без дат, цену заказчика и индексы считать нельзя", "обе даты и общий срок записаны в акте и совпадают с графиком производства работ"),
                       ("Нет количеств", "«ремонт кровли» без площади и перечня", "каждый дефект с единицей измерения и объёмом, приложены фото и схема"),
                       ("Акт составлен после работ", "смета по факту, акт задним числом", "акт утверждён до закупки и договора, смета составлена по нему")]))

    s += _sec("3", "Смета: только локальная",
              _p("Согласно Инструкции № 116 (с 01.01.2026) при текущем ремонте составляется только локальная смета, а объектных смет и сводного сметного расчёта нет. Локальную смету составляют по видам работ на основании дефектного акта.")
              + _tbl(["Элемент", "Как определяется"], [
                  ["Зарплата рабочих", "стоимость человеко-часа рабочего 4 разряда в размере, установленном Минстройархитектуры"],
                  ["Машины и механизмы", "по республиканской базе цен на ресурсы, при отсутствии расчётом"],
                  ["Материалы", "по республиканской базе, при отсутствии по мониторингу цен; при текущем ремонте мониторинг может проводить сам разработчик сметы с документальным подтверждением"],
                  ["ОХР и ОПР, плановая прибыль", "по нормам Минстройархитектуры от зарплаты рабочих и машинистов; для текущего ремонта к плановой прибыли применяется коэффициент 1,115"],
                  ["Прочие средства", "страховые взносы, непредвиденные, временные здания, содержание заказчика и др. по главе 5 Инструкции; отходы и разработка сметы только если обоснованы в акте"]])
              + _p("История человеко-часа показывает, как быстро устаревают цифры: 12,46 руб. действовало с апреля 2024 года, 14,47 руб. с 1 мая 2025 года. Значение на 2026 год берите из действующего постановления Минстройархитектуры. "
                   "Проценты норм ОХР, ОПР и плановой прибыли тоже берут из постановления № 146 по виду работ и месту (город, село), см. статью «Из чего состоит цена».")
              + _errs([("Взяты нормы для нового строительства", "применили строку «строительные работы», хотя работы ремонтные", "выбрана строка норм для работ по ремонту зданий и сооружений"),
                       ("Забыт коэффициент текущего ремонта", "плановая прибыль посчитана без коэффициента 1,115", "коэффициент применён к норме плановой прибыли, как требует постановление № 146"),
                       ("Старое значение человеко-часа", "в смету внесена ставка прошлого года", "в смете ставка, действующая на дату составления сметы")]))

    s += _sec("4", "Цена и договор",
              _p("Договор подряда на текущий ремонт это полноценный договор строительного подряда. Упрощено только документооборот, а не правила договора. К договору прилагают дефектный акт, локальную смету, график производства работ, график платежей и расчёт неизменной цены.")
              + _tbl(["Понятие", "Что это"], [
                  ["Цена заказчика", "сметная стоимость на дату начала работ из дефектного акта с прогнозными индексами и НДС; индекс берут по месяцам срока работ, а стоимость делят по месяцам пропорционально дням"],
                  ["Цена предложения подрядчика", "считается по смете заказчика с конкурсным коэффициентом либо по своей смете на ту же дату; подрядчик вправе заменить материалы и нормы, если качество и характеристики результата сохраняются; расчёт нужно подтвердить"],
                  ["Неизменная цена", "после заключения договора корректируется только по основаниям, перечисленным в Положении № 1553 и договоре"]])
              + _p("Что в этой части особенно важно запомнить:")
              + _ul(["рост цены материалов сам по себе не повод для пересмотра неизменной цены: этот риск несёт подрядчик, экономия тоже остаётся у него при достижении нужных характеристик;",
                     "для бюджетных средств основания корректировки перечислены в подп. 1.8 п. 1 постановления Совмина № 395, для собственных средств их надо прописать в договоре;",
                     "материалы заказчика в неизменную цену не входят, их перечень и график поставки утверждают отдельно;",
                     "в 2026 году Положение № 1553 и правила закупок за счёт собственных средств менялись, поэтому условия о корректировке цены сверяют с действующей редакцией на дату подписания договора."]))

    s += _sec("5", "Закупка работ",
              _p("Процедура зависит от суммы и источника денег. Для бюджетных организаций это Закон № 419-З «О государственных закупках товаров (работ, услуг)» и постановление № 395, для остальных правила закупок за счёт собственных средств, которые обновлялись в 2026 году.")
              + _ul(["<b>Порог считается по объекту</b>, а не по одной сделке. Дробление работ на несколько договоров, чтобы уйти от процедуры, это нарушение, его находят по плану закупок и реестру договоров.",
                     "<b>Дефектный акт и смету требуют всегда</b>, какую бы процедуру вы ни выбрали, они часть документации.",
                     "<b>Пороги заданы в базовых величинах</b>, поэтому их пересчитывают при каждом изменении базовой величины. Действующие значения и пределы изменения объёма договора берите из текста акта на дату закупки.",
                     "<b>Предмет закупки</b> описывают через объёмы из дефектного акта. Если точный объём заранее неизвестен, закон допускает закупку по цене за единицу с оплатой по факту в пределах предельной стоимости."])
              + _note("Пределы изменения объёма договора различаются для бюджетных и собственных средств и менялись в 2026 году. Не переносите предел с одного режима на другой."))

    s += _sec("6", "Дополнительные работы",
              _p("Самая частая причина споров: подрядчик нашёл скрытый дефект, которого нет в акте. Порядок один: сообщить, оформить, согласовать, только потом выполнять.")
              + _ul(["подрядчик сразу письменно сообщает заказчику о работах, не предусмотренных дефектным актом и сметой, и о росте стоимости;",
                     "стороны подписывают акт об обнаружении, при необходимости с инженерной организацией;",
                     "на допработы составляют отдельную локальную смету со знаком «плюс», а исключённые позиции со знаком «минус»; заменять выпущенную смету новой нельзя;",
                     "дополнительное соглашение подписывают до начала допработ: работы без него рискуют остаться неоплаченными;",
                     "срок работ пересматривают, если допработы влияют на срок, а график платежей и график производства работ обновляют."])
              + _note("Предел увеличения договора за счёт допработ задан актом о закупках и зависит от источника средств. Проверьте его в действующем тексте до подписания соглашения."))

    s += _sec("7", "Приёмка и расчёты",
              _p("Работы принимают актом формы С-2а по локальной смете с разбивкой по элементам затрат. Акт составляют на полностью законченный вид работ по графику, частично выполненный вид включают по соглашению сторон при определённом объёме.")
              + _ul(["фактическая стоимость ниже неизменной цены при достигнутых характеристиках это экономия подрядчика, оплата идёт по неизменной цене;",
                     "работы ненадлежащего качества не принимают и не оплачивают до устранения дефектов, как и технологически связанные с ними работы;",
                     "скрытые работы принимают по актам освидетельствования до закрытия конструкций;",
                     "форму акта и порядок заполнения сверяйте с действующей инструкцией на дату приёмки."]))

    s += _sec("8", "Отходы",
              _p("Отходы, подлежащие хранению, использованию, обезвреживанию или захоронению, учитывают в смете справочно: после итога приводят массу каждого вида. Средства на обращение с ними включают в смету только если они обоснованы в дефектном акте. "
                 "По договору подрядчик обязан регулярно убирать площадку и освободить её по окончании работ, а экологический налог и вывоз определяют по фактам и документам.")
              + _ul(["в акте перечислите виды отходов и ожидаемую массу;", "в договоре закрепите, кто вывозит и кто платит;", "храните документы приёма и вывоза: без них затраты не подтвердить."]))

    s += _sec("9", "Учёт",
              _p("Текущий ремонт это расходы отчётного периода, а не увеличение стоимости основного средства. Если фактически выполнен капитальный ремонт или модернизация, затраты могут подлежать капитализации, поэтому квалификация работ влияет на налог на прибыль и амортизацию. "
                 "Обязательные первичные документы: дефектный акт, смета, договор, акты и справки о стоимости, документы по отходам и материалам. Конкретные проводки и налоговые последствия согласуйте с главным бухгалтером по действующим нормам."))

    s += _sec("10", "Смешанные договоры",
              _p("Если в одном договоре текущий ремонт и работы, требующие проекта (например, новая инженерная система), к ним применяют правила для работ с проектом: проект, аттестат, уведомление. Не прячьте капитальные работы под видом текущего ремонта.")
              + _ul(["разделите виды работ в договоре и смете на части с разным режимом;",
                     "для каждой части определите нужные документы и требования к подрядчику;",
                     "для длительного обслуживания здания не растворяйте ремонт в договоре на содержание: оформите акт, смету и отдельный договор подряда."]))

    s += _sec("11", "Чек-лист заказчика",
              _ul(["вид работ определён и записан приказом (текущий, не капитальный, не модернизация);",
                   "дефектный акт по утверждённой форме: объёмы, условия, даты начала и срока, обоснование прочих средств;",
                   "локальная смета составлена по акту и действующей Инструкции, ставки и нормы на дату сметы;",
                   "процедура закупки выбрана по сумме по объекту, дробления нет;",
                   "в договоре: дефектный акт, смета, график работ, график платежей, расчёт неизменной цены, основания корректировки, порядок допработ;",
                   "перечень материалов заказчика и график их поставки утверждены;",
                   "допработы оформляются до выполнения; приёмка по С-2а; документы по отходам собраны."]))

    s += _box("Сверяйте с текстом акта",
              "Эти параметры меняются, поэтому в статье их нет: значение человеко-часа на текущий год, проценты норм ОХР и плановой прибыли, пороги закупок и базовая величина, "
              "предельные проценты изменения договора, прогнозные индексы по месяцам, действующая редакция Положения № 1553 и правил закупок за счёт собственных средств. "
              "Статья справочная и не заменяет консультацию юриста или сметчика.")
    return s
